"""Kaggle runner: Beta v2.1 C1 true time-OOS ranking comparison (Seg155/Seg19/Seg8)."""

from __future__ import annotations

import base64
import io
import json
import os
import shutil
import subprocess
import sys
import tarfile
import time
from pathlib import Path

EMBEDDED_KRONOS_ARCHIVE_B64 = """

"""

OUTPUT_NAME = "beta_v2_1_c1_rank_oos"
EXPERIMENT_NAME = "beta_v2_1_c1_rank_oos"
MODEL_REPO = "luckfu/Kronos-A-Share-Beta-V2-1"
EXPECTED_TOKENIZER_SHA256 = (
    "59d85f6af76a2c3b8240ea06cb21db4213b4eeca053f246b23e29cf832fc6bee"
)

CHECKPOINTS = (
    (
        "seg155_forecast_best",
        "**/kronos-beta-v21-c1-seg155-forecast-best/**/checkpoints/best_model",
        "**/kronos-beta-v21-c1-seg155-forecast-best/checkpoints/best_model",
    ),
    (
        "seg19_rank_frozen_best",
        "**/kronos-beta-v21-c1-rank-frozen-seg19-best/**/checkpoints/best_model",
        "**/kronos-beta-v21-c1-rank-frozen-seg19-best/checkpoints/best_model",
    ),
    (
        "seg8_rank_unfreeze_best",
        "**/kronos-beta-v21-c1-rank-unfreeze-seg8-best/**/checkpoints/best_model",
        "**/kronos-beta-v21-c1-rank-unfreeze-seg8-best/checkpoints/best_model",
    ),
)


def emit(message: str) -> None:
    line = str(message)
    print(line, flush=True)
    log = Path("/kaggle/working") / OUTPUT_NAME / "run.log"
    log.parent.mkdir(parents=True, exist_ok=True)
    with log.open("a", buffering=1) as handle:
        handle.write(line + "\n")


def sha256_file(path: Path) -> str:
    import hashlib

    digest = hashlib.sha256()
    with path.open("rb") as handle:
        for chunk in iter(lambda: handle.read(1024 * 1024), b""):
            digest.update(chunk)
    return digest.hexdigest()


def extract_bundle(target: Path) -> Path:
    target.mkdir(parents=True, exist_ok=True)
    raw = base64.b64decode(EMBEDDED_KRONOS_ARCHIVE_B64.strip())
    with tarfile.open(fileobj=io.BytesIO(raw), mode="r:gz") as archive:
        archive.extractall(target)
    root = target / "Kronos"
    if not (root / "model").is_dir():
        raise RuntimeError(f"Embedded archive missing model/ under {root}")
    return root


def download_tokenizer(target: Path) -> Path:
    target.mkdir(parents=True, exist_ok=True)
    try:
        from modelscope.hub.snapshot_download import snapshot_download
    except ImportError:
        subprocess.check_call([sys.executable, "-m", "pip", "install", "-q", "modelscope"])
        from modelscope.hub.snapshot_download import snapshot_download
    emit(f"phase=download_tokenizer repo={MODEL_REPO}")
    snapshot_download(MODEL_REPO, local_dir=str(target))
    tokenizer = target / "tokenizer"
    if not (tokenizer / "config.json").is_file():
        # some snapshots nest tokenizer differently
        matches = list(target.glob("**/tokenizer/config.json"))
        if not matches:
            raise RuntimeError(f"Tokenizer not found under {target}")
        tokenizer = matches[0].parent
    tok_sha = sha256_file(tokenizer / "model.safetensors")
    emit(f"phase=tokenizer_ready path={tokenizer} sha256={tok_sha}")
    if EXPECTED_TOKENIZER_SHA256 and tok_sha != EXPECTED_TOKENIZER_SHA256:
        raise RuntimeError(
            f"Tokenizer SHA mismatch: {tok_sha} != {EXPECTED_TOKENIZER_SHA256}"
        )
    return tokenizer


def find_checkpoint(input_root: Path, label: str, patterns: tuple[str, ...]) -> Path:
    matches = []
    for pattern in patterns:
        for path in input_root.glob(pattern):
            if (path / "config.json").is_file() and (
                (path / "model.safetensors").is_file() or (path / "pytorch_model.bin").is_file()
            ):
                matches.append(path.resolve())
    matches = sorted(set(matches))
    if len(matches) != 1:
        raise RuntimeError(f"{label}: expected one checkpoint, found {matches}")
    emit(f"phase=checkpoint label={label} path={matches[0]}")
    return matches[0]


def main() -> None:
    started = time.time()
    input_root = Path("/kaggle/input")
    working = Path("/kaggle/working") / OUTPUT_NAME
    working.mkdir(parents=True, exist_ok=True)
    emit(f"phase=start experiment={EXPERIMENT_NAME}")

    gpu = subprocess.run(
        ["nvidia-smi", "--query-gpu=name,memory.total", "--format=csv,noheader"],
        capture_output=True,
        text=True,
        check=False,
    ).stdout.strip()
    emit(f"phase=gpu\n{gpu}")

    repo = extract_bundle(working / "src")
    sys.path.insert(0, str(repo))
    sys.path.insert(0, str(repo / "finetune"))

    tokenizer = download_tokenizer(working / "pretrained")
    checkpoints = []
    for label, *patterns in CHECKPOINTS:
        checkpoints.append((label, str(find_checkpoint(input_root, label, tuple(patterns)))))

    cmd = [
        sys.executable,
        str(repo / "finetune" / "evaluate_beta_v21_time_oos.py"),
        "--input-root",
        str(input_root),
        "--output-dir",
        str(working / "results"),
        "--tokenizer",
        str(tokenizer),
        "--batch-size",
        os.environ.get("KRONOS_OOS_BATCH_SIZE", "32"),
    ]
    for label, path in checkpoints:
        cmd.extend(["--checkpoint", label, path])
    max_samples = os.environ.get("KRONOS_OOS_MAX_SAMPLES", "").strip()
    if max_samples:
        cmd.extend(["--max-samples", max_samples])

    emit("phase=evaluate_cmd " + " ".join(cmd))
    env = os.environ.copy()
    env["PYTHONUNBUFFERED"] = "1"
    env["PYTHONPATH"] = str(repo) + os.pathsep + str(repo / "finetune") + os.pathsep + env.get("PYTHONPATH", "")
    result = subprocess.run(cmd, env=env)
    emit(f"phase=evaluate_exit code={result.returncode} seconds={time.time()-started:.1f}")
    if result.returncode != 0:
        raise SystemExit(result.returncode)

    # Mirror comparison to working root for easy download
    src = working / "results" / "comparison.json"
    if src.is_file():
        shutil.copy2(src, working / "comparison.json")
        emit("phase=comparison\n" + src.read_text()[:4000])
    emit(f"phase=done total_seconds={time.time()-started:.1f}")


if __name__ == "__main__":
    main()
